import {collectionLabs,seasons,seasonAt,createCollectionState,updateCollectionState} from './collection-lab-data.js';
import {CollectionLabScene} from './collection-lab-scene.js';
const id=new URLSearchParams(location.search).get('object'),config=collectionLabs[id],root=document.getElementById('lab-root');let state=createCollectionState(),scene;
document.title=config.name+' · 器物实验室 · 大江大湖间的符号——色彩与文化记忆';document.body.dataset.object=id;document.querySelectorAll('[data-lab]').forEach(a=>{if(a.dataset.lab===id){a.setAttribute('aria-current','page');a.parentElement.scrollLeft=Math.max(0,a.offsetLeft-a.parentElement.offsetLeft-20)}});
const button=(name,label)=>`<button data-action="${name}">${label}</button>`;
function controls(){if(id==='duck')return `<h2 class="side-heading">鸟头，试着转一转。</h2><p>拖动模型的鸟头，或移动下方滑块。再看看背上的盖子。</p><label class="explore-range">鸟头方向 <output id="head-value">0°</output><input id="head-angle" type="range" min="-160" max="160" value="0" aria-label="鸟头转动角度"></label><div class="lab-actions">${button('left','向左转 ↶')}${button('right','向右转 ↷')}</div><button class="lab-primary" data-action="lid">提起背盖 ↑</button><label class="explore-range">背盖高度 <output id="lid-value">合拢</output><input id="lid-amount" type="range" min="0" max="100" value="0" aria-label="背盖提起高度"></label>`;
 if(id==='jz-458')return `<h2 class="side-heading">打开，才知道里面能做什么。</h2><p>提起盒盖，拖动前面的耳杯进盒内。也可以用按钮逐只摆放。</p><button class="lab-primary" data-action="lid">提起盒盖 ↑</button><label class="explore-range">盒盖高度 <output id="lid-value">合拢</output><input id="lid-amount" type="range" min="0" max="100" value="0" aria-label="盒盖提起高度"></label><div class="cup-progress" aria-label="示意耳杯收纳进度"><span>已经收好</span><b id="cup-count">0 / 3</b><div>${[0,1,2].map(i=>`<i data-cup="${i}"></i>`).join('')}</div></div><div class="lab-actions">${button('put','收好一只耳杯 ＋')}${button('take','取出一只耳杯 −')}</div><p class="touch-hint">三只为互动练习数量，不表示实际出土数量。</p>`;
 return `<h2 class="side-heading">从一个“斗”字，转到四时。</h2><p>先从箱盖中展开星图，再转动斗柄。试着让它朝向不同的方向。</p><button class="lab-primary" data-action="stars">从箱盖展开星图 ✧</button><div class="season-controls" hidden><div class="season-reading"><strong id="season-name">春</strong><span id="season-copy">斗柄朝东，天下皆春。</span></div><div class="season-buttons">${seasons.map((s,i)=>`<button data-season="${i}" aria-pressed="${i===0}">${s.name}<small>${s.direction}</small></button>`).join('')}</div><label class="explore-range">斗柄方向 <output id="angle-value">东 · 0°</output><input id="season-angle" type="range" min="0" max="359" value="0" aria-label="斗柄转动方向"></label><p class="touch-hint">星点和二十八宿名称为方位示意，不按真实星距；箱盖原文以实物照片为准。</p></div>`;
}
root.innerHTML=`<div class="lab-layout collection-layout"><section class="lab-viewport"><div class="lab-stage"></div><div class="lab-title"><span class="lab-kicker">${config.kicker}</span><h1>${config.title}</h1><p>${config.intro}</p></div><div class="lab-camera" aria-label="观察角度"><button data-camera="home">全貌 ⤢</button><button data-camera="front">正面</button><button data-camera="back">背面</button><button data-camera="top">俯视</button></div><div class="collection-labels"></div><div class="scene-action-buttons">${id==='duck'?'<button data-hotspot="head">↔ 转动鸟头</button><button data-hotspot="lid">↑ 打开背盖</button>':id==='jz-458'?'<button data-hotspot="lid">↑ 提起盒盖</button>':'<button data-hotspot="lid">✧ 展开箱盖星图</button>'}</div><div class="lab-scene-note"><span>${config.action}</span>空处拖动旋转 · 滚轮缩放 · 方向键转动</div><div class="lab-loader" role="status"><b>正在展开${config.name}</b><span>载入三维模型</span><progress max="1" value="0"></progress></div></section><aside class="lab-side"><div class="lab-panel-label">动手之后，发现什么</div>${controls()}<p class="collection-feedback" role="status"></p><section class="knowledge"><div class="lab-panel-label">器物里藏着的想法</div><h3 class="fact-title"></h3><p class="fact-copy"></p></section><div class="lab-actions">${button('photo','对照实物照片 ↗')}${button('reset','重新探索 ↺')}</div>${config.detail?`<a class="lab-object-link" href="${config.detail}">进入器物档案 ↗</a>`:''}<details class="lab-sources"><summary>资料与示意说明</summary><p>${config.note}</p><p>三维表面来自用户提供的 Tripo 模型，生成纹理不能替代实物图像。</p><a href="${config.source}" target="_blank" rel="noopener">${config.sourceLabel} ↗</a>${id==='chest'?'<p><a href="https://www.ctwx.tsinghua.edu.cn/__local/4/C0/54/2A1C2CDD8FFFB14724AAE052B86_C1E50845_CF90C.pdf" target="_blank" rel="noopener">二十八宿名称对照研究 ↗</a></p>':''}</details></aside></div><dialog class="lab-photo-dialog"><header><strong>${config.name} · 实物照片</strong><button data-action="close-photo" aria-label="关闭实物照片">×</button></header><img src="${config.photo}" alt="${config.name}实物照片"><footer><span>${config.photoCredit}</span><a href="${config.photoSource}" target="_blank" rel="noopener">照片来源 ↗</a></footer></dialog>`;
function fact(key){const f=config.facts[key]||config.facts[Object.keys(config.facts)[0]];root.querySelector('.fact-title').textContent=f[0];root.querySelector('.fact-copy').textContent=f[1]}
function feedback(text){root.querySelector('.collection-feedback').textContent=text}
function ui(){root.querySelectorAll('[data-action=lid]').forEach(b=>b.textContent=state.lid>.5?(id==='duck'?'放回背盖 ↓':'合上盒盖 ↓'):(id==='duck'?'提起背盖 ↑':'提起盒盖 ↑'));const lid=root.querySelector('#lid-amount');if(lid){lid.value=Math.round(state.lid*100);root.querySelector('#lid-value').textContent=state.lid<.05?'合拢':Math.round(state.lid*100)+'%'}
 if(id==='duck'){root.querySelector('#head-angle').value=state.head;root.querySelector('#head-value').textContent=Math.round(state.head)+'°'}
 if(id==='jz-458'){const n=state.cups.filter(Boolean).length;root.querySelector('#cup-count').textContent=n+' / 3';root.querySelectorAll('[data-cup]').forEach(b=>b.classList.toggle('filled',state.cups[+b.dataset.cup]));root.querySelector('[data-action=put]').disabled=state.lid<=.7||n===3;root.querySelector('[data-action=take]').disabled=state.lid<=.7||n===0}
 if(id==='chest'){const s=seasons[seasonAt(state.angle)];root.querySelector('.season-controls').hidden=!state.stars;root.querySelector('[data-action=stars]').textContent=state.stars?'收回星图，回看衣箱 ↓':'从箱盖展开星图 ✧';root.querySelector('#season-name').textContent=s.name;root.querySelector('#season-name').style.color=s.color;root.querySelector('#season-copy').textContent=s.copy;root.querySelector('#season-angle').value=Math.round(state.angle);root.querySelector('#angle-value').textContent=s.direction+' · '+Math.round(state.angle)+'°';root.querySelectorAll('[data-season]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.season===seasonAt(state.angle))))}
 root.querySelectorAll('[data-hotspot]').forEach(b=>{const p=b.dataset.hotspot;b.textContent=p==='head'?'↔ 转动鸟头':id==='chest'?(state.stars?'收回星图 ↓':'✧ 展开箱盖星图'):state.lid>.5?'放回盖子 ↓':'↑ 打开盖子'});root.querySelectorAll('[data-action],[data-hotspot],input,[data-season]').forEach(b=>{if(!scene?.ready&&!['photo','close-photo'].includes(b.dataset.action))b.disabled=true});document.body.dataset.lid=String(state.lid);document.body.dataset.cups=state.cups.filter(Boolean).length;document.body.dataset.stars=String(state.stars);document.body.dataset.season=seasons[seasonAt(state.angle)].name;
}
function action(a){if(!scene?.ready)return;const before=state;state=updateCollectionState(state,a);scene.setState(state);if(a.type==='head'){fact('head');feedback('颈下的圆榫，让头部可以转动。')}if(a.type==='lid'){fact(state.lid>.4?'lid':id==='jz-458'?'closed':'body');feedback(state.lid>.7?(id==='jz-458'?'盒内露出来了，拖动耳杯试着收好。':'背上的开口露出来了。绕到上方看看。'):'盖与器身重新连成完整轮廓。')}if(a.type==='cup'){fact('cup');feedback(state.lid<=.7?'先提起盒盖，再摆放耳杯。':state.cups.filter(Boolean).length===3?'三只示意耳杯都收好了，可以合上盒盖。':'耳杯留在盒里，动物形的器身也有实用的一面。')}if(a.type==='stars'){fact('lid');feedback(state.stars?'拖动发亮的斗柄，或点右侧四时按钮。':'回到衣箱。再看看原来的箱盖。');if(!state.stars)scene.view('home')}if(a.type==='angle'){fact('season');feedback(seasons[seasonAt(state.angle)].copy)}if(a.type==='reset'){scene.view('home');fact(id==='duck'?'head':'lid');feedback('重新开始，试着碰一碰器物。')}ui()}
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.camera){scene?.view(b.dataset.camera);return}if(b.dataset.season!==undefined){action({type:'angle',value:seasons[+b.dataset.season].angle});return}if(b.dataset.hotspot){if(b.dataset.hotspot==='head')action({type:'head',value:state.head>=130?-140:state.head+45});else action({type:id==='chest'?'stars':'lid',value:id==='chest'?!state.stars:1-state.lid});return}const t=b.dataset.action;if(t==='photo')root.querySelector('dialog').showModal();if(t==='close-photo')root.querySelector('dialog').close();if(t==='left'||t==='right')action({type:'head',value:state.head+(t==='left'?-45:45)});if(t==='lid')action({type:'lid',value:1-state.lid});if(t==='stars')action({type:'stars',value:!state.stars});if(t==='put'||t==='take'){const i=state.cups.findIndex(v=>t==='put'?!v:v);if(i>=0)action({type:'cup',index:i,inside:t==='put'})}if(t==='reset')action({type:'reset'})});
root.querySelector('#head-angle')?.addEventListener('input',e=>action({type:'head',value:+e.target.value}));root.querySelector('#lid-amount')?.addEventListener('input',e=>action({type:'lid',value:+e.target.value/100}));root.querySelector('#season-angle')?.addEventListener('input',e=>action({type:'angle',value:+e.target.value}));
fact(id==='duck'?'head':'lid');feedback(config.intro);
try{scene=new CollectionLabScene(root.querySelector('.lab-stage'),id,config,{onAction:action,onPart:fact,onProgress:v=>{const el=root.querySelector('progress');if(v===null)el.removeAttribute('value');else el.value=v},onReady:()=>{root.querySelector('.lab-loader').hidden=true;root.querySelectorAll('button,input').forEach(b=>b.disabled=false);document.body.dataset.ready='true';if(id==='chest'){const labels=root.querySelector('.collection-labels');scene.labels.forEach(l=>{const el=document.createElement('span');el.textContent=l.name;el.className='star-label '+l.kind;el.hidden=true;labels.append(el);l.el=el})}ui()},onError:m=>{feedback(m);document.body.dataset.error='true'},onFrame:()=>{root.querySelectorAll('[data-hotspot]').forEach(b=>{const p=scene.screen(scene.anchor(b.dataset.hotspot));b.hidden=!p.visible;b.style.left=Math.max(75,Math.min(scene.width-75,p.x))+'px';b.style.top=Math.max(150,Math.min(scene.height-80,p.y-23))+'px'});if(id==='chest')scene.labels.forEach(l=>{if(!l.el)return;const p=scene.screen(scene.starGroup.localToWorld(l.p.clone()));l.el.hidden=!state.stars||!p.visible;l.el.style.left=p.x+'px';l.el.style.top=p.y+'px'})}});ui();await scene.load()}catch(e){console.error(e);root.querySelector('.lab-loader').innerHTML='<b>模型暂时未能打开</b><span>请刷新重试，或先对照实物照片。</span>';document.body.dataset.error='true'}
window.addEventListener('pagehide',e=>{if(e.persisted)scene?.suspend();else scene?.dispose()});window.addEventListener('pageshow',e=>{if(e.persisted)scene?.resume()});
